const c=$input.first().json;
if(c.automaticMemory && c.state) {
  const s=JSON.parse(JSON.stringify(c.state));
  // Bound built-in memory. This is a single daily digest, not an archive.
  const events=Object.values(s.events).sort((a,b)=>Date.parse(b.checked_at)-Date.parse(a.checked_at)).slice(0,100);
  s.events=Object.fromEntries(events.map(e=>[e.id,e]));
  s.sources=Object.fromEntries(Object.entries(s.sources).sort((a,b)=>Date.parse(b[1].verified_at)-Date.parse(a[1].verified_at)).slice(0,25));
  s.backlog=s.backlog.slice(0,50).map(p=>({url:p.url,title:p.title||'',priority:p.priority||0,trustedRef:Boolean(p.trustedRef),reference:p.reference||''}));
  const cut=Date.now()-7*86400000;
  s.deliveries=Object.fromEntries(Object.entries(s.deliveries).filter(([,r])=>Date.parse(r.at)>=cut));
  if(s.lock && c.phase==='done')s.lock=null;
  $getWorkflowStaticData('global').hackathonRadar=s;
}
return [{json:c,pairedItem:{item:0}}];
